import json,csv,hashlib,pathlib,datetime,zoneinfo
P=pathlib.Path
read=lambda p:json.loads(P(p).read_text())
qa=read('evidence/c7-v598-verification/results.json');suites=read('evidence/c7-v598-final-checks/results.json')['runs'];public=read('evidence/c7-v598-public/results.json')
assert len(qa)==5 and len(suites)==8 and len(public)==4 and all(r['code']==0 for r in qa+suites+public)
perf=read('evidence/c7-v598-flight-abba/results.json');assert len(perf['rows'])==12 and not perf['errors']
summary=[]
for w in [390,1440,2560]:
 values={m:sum(r['activeRenderedFPS'] for r in perf['rows'] if r['width']==w and r['mode']==m)/2 for m in ['baseline','candidate']}
 summary.append({'width':w,**values,'percent':(values['candidate']/values['baseline']-1)*100})
receipt=read(P.home()/'.config/volnami-c7-preview/harvis-v598.json');assert receipt['updated'] and receipt['url']=='https://breezy-hazel-428.harvis.page'
expiry=datetime.datetime.fromisoformat(receipt['expiresAt'].replace('Z','+00:00')).astimezone(zoneinfo.ZoneInfo('Europe/Moscow')).strftime('%d.%m.%Y %H:%M:%S МСК')
pkg=read('evidence/c7-v598-package.json');assert pkg['files']==107 and pkg['allEntryHashesExact']
assert hashlib.sha256(P('artifacts/c7-preview-2026-10-29-v598.zip').read_bytes()).hexdigest()==pkg['archiveSHA256']
backups=read('backups/c7-v598-start-2026-10-29/manifest.json')
for f,h in backups.items():assert hashlib.sha256((P('backups/c7-v598-start-2026-10-29')/f).read_bytes()).hexdigest()==h,f
protected=read('evidence/c7-v598-preservation/results.json');assert protected['checked']==150 and not protected['failed']
net=read('evidence/c7-v598-public/chromium/results.json')
network=[{'width':r['width'],'runtimeBytes':r['delivery']['worldBytes'],'resourceBytes':r['delivery']['resourceBytes']} for r in net['runs']]
status={'version':'v598','at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':receipt['url']+'/c7/','expiresAt':receipt['expiresAt'],'tenOfTen':False,'open':['G04 REWORK: bank/slope/crown match','G07 REWORK: FPS and network budgets; 2x not reached','G08 OPEN: owner claim deferred; no guaranteed week'],'notRun':['physical iOS','physical Android','weak GPU','native Safari','VoiceOver','TalkBack'],'performance':summary,'network':network,'functionalSuites':len(suites),'publicScenarios':sum(len(read(f'evidence/c7-v598-public/{e}/results.json')['runs']) for e in ['chromium','firefox','webkit']),'portablePixelPairs':33,'protected':150,'backups':len(backups),'package':pkg}
P('evidence/c7-v598-completion-status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2))
perftext='; '.join(f"{r['width']}: {r['baseline']:.2f}→{r['candidate']:.2f} FPS ({r['percent']:+.1f}%)" for r in summary)
headline=f'''> **Текущий выпуск v598 · 29.10.2026.** https://breezy-hazel-428.harvis.page/c7/ . Однократная подготовка травы на GPU, компактные координаты теней, отсечение невидимой области отражения. Полный сайт B/C/C/B: {perftext}. 8/8 функциональных suites,107 публичных SHA и7 публичных сценариев прошли. **×2 и10/10 не достигнуты: G04/G07 REWORK, G08 OPEN.** Геометрия берега/склонов/крон не исправлена. Физические устройства/native Safari/дикторы NOT_RUN. Preview до {expiry}; неделя не гарантирована. Отчёт: `design/c7-release-v598-2026-10-29.md`.'''
for f in ['design/c7-master-tz-2026-10-25.md','design/c7-execution-plan-v572-2026-10-29.md','design/c7-current-world-passport-2026-10-26.md']:
 p=P(f);s=p.read_text();assert '<!-- v598-status-start -->' not in s
 i=s.index('\n')+1;s=s[:i]+'\n<!-- v598-status-start -->\n'+headline+'\n<!-- v598-status-end -->\n'+s[i:];s=s.replace('**Текущий выпуск v597','**Предыдущий выпуск v597');p.write_text(s)
p=P('design/c7-release-v598-2026-10-29.md');s=p.read_text();s=s.replace('Статус: кандидат проверяется; до подтверждённой публикации текущий preview — v597.','Статус: v598 опубликована и проверена на существующей ссылке.');s=s.replace('Результаты полного сайта и выпуска будут записаны после завершения проверок.','Результаты полного сайта и выпуска подтверждены ниже.');s+='\n\n## Итог выпуска\n\n'+headline+'\n\n| Размер | v597 FPS | v598 FPS | Изменение |\n|---|---:|---:|---:|\n'+'\n'.join(f"| {r['width']} | {r['baseline']:.2f} | {r['candidate']:.2f} | {r['percent']:+.2f}% |" for r in summary)+f'''\n\nПакет107файлов, {pkg['packageBytes']}байт; ZIP{pkg['archiveBytes']}байт. Полный runtime по публичному Resource Timing: '''+', '.join(f"{r['width']}: {r['runtimeBytes']/1e6:.2f}МБ" for r in network)+f'''. Новый проход не уменьшал сетевой бюджет. 150 защищённых файлов и{len(backups)} резервных SHA точны. Сохранены исходные незакоммиченные изменения.\n\nПроверки: `evidence/c7-v598-verification`, `c7-v598-final-checks`, `c7-v598-flight-abba`, `c7-v598-runtime-pixels`, `c7-v598-reverse-control`, `c7-v598-reverse-firefox`, `c7-v598-reverse-webkit`, `c7-v598-lifecycle`, `c7-v598-public`, `c7-v598-public-delivery`, `c7-v598-preservation`.\n''';p.write_text(s)
p=P('design/c7-execution-journal-2026-10-23-r2.md');s=p.read_text();assert '### EXEC113 —' not in s;s+='\n\n### EXEC113 — v598,29.10.2026\n\n'+headline+f'\n\nНезакоммиченная работа сохранена:150protected/{len(backups)}backup SHA точны. Без агентов, окон и коммитов. Неполучившие полезного выигрыша LOD-normal/ground-shadow/PMREM-cache/CPU-occlusion варианты отклонены. Нового Next build нет: native ES-module release с98 сохранёнными статическими файлами.\n';p.write_text(s)
p=P('design/c7-execution-plan-v572-2026-10-29.md');s=p.read_text();s+='\n\n## EXEC113 — выполненный этап\n\n- [x] Подготовка неизменных величин травы и уменьшение shadow-varyings; перенос в реальный runtime.\n- [x] Консервативное отсечение отражения с сохранённым разрешением.\n- [x] Парные FPS,33состояния, контроль reverse, lifecycle и8наборов; проверенный выпуск.\n- [ ] ×2/40–60FPS: не достигнуты, дальнейшая переработка растительного/земляного света.\n- [ ] Художественное совпадениеimage3, физические устройства, native Safari/дикторы и гарантия недели.\n';p.write_text(s)
p=P('design/c7-performance-audit-2x-2026-10-29.md');s=p.read_text();s+='\n\n## Реализация EXEC113/v598\n\nЧасть пунктов1/3 реализована: статические параметры травы на GPU, compact shadow varyings и crop отражённой камеры. Пункт2 (PMREM-cache) проверен и отклонён из-за малой пользы и памяти. Результат полного сайта: '+perftext+'. Проверки/публикация завершены, но критерий×2 в пункте5 не выполнен. Отчёт: `design/c7-release-v598-2026-10-29.md`.\n';p.write_text(s)
p=P('design/c7-current-world-passport-2026-10-26.md');s=p.read_text();s+='\n\n## Параметры v598\n\nAuthoring world SHA256: '+hashlib.sha256(P('lab/c7-scene/world.js').read_bytes()).hexdigest()+'. Runtime world SHA256: '+hashlib.sha256(P('public/3d/c7/runtime-v395/world.js').read_bytes()).hexdigest()+'. GPU precompute grass-static: неизменные sin/cos,tuft-noise и physical normal; дополнительные8байт атрибутов/стебель. Временные TF/VAO/buffers/program удаляются; выход хранится наCPU для context restore. Shadow-varyings ближней/дальней травы компактны, матрицы/normal bias сохранены. Reflection crop меняет frustum/scissor только вне области водного зеркала с64px/8%guard; исходный размер,MSAA,частота обновления и проекция выборок сохранены. Параметры света/геометрия/камера/DPR остаются прежними. Lifecycle restore exact,dispose/abort проверены. Исторические параметры ниже не обозначают новый выпуск.\n';p.write_text(s)
p=P('design/c7-working-matrix-2026-10-26.csv');rows=list(csv.DictReader(p.read_text(encoding='utf-8-sig').splitlines()));fields=list(rows[0])
for r in rows:
 if r['id']=='G07':r['actual']='v598: '+perftext+'. ×2/40–60FPS не достигнуты. Сетевой бюджет mobile3–6МБ/desktop5–10МБ остаётся открытым; фактические Resource Timing в отчёте. Физические устройства/nativeSafari/дикторы NOT_RUN.';r['status']='REWORK'
 elif r['id']=='G08':r['actual']='v598 опубликована:107 HTTPS SHA и7 публичных сценариев проверены. Receipt до '+expiry+'. Закрепление отложено; гарантированной недели нет.';r['status']='OPEN'
 elif r['id']=='G04':r['actual']='v598: ускорение сохранило композицию; отличия освещённого берега, склонов и крон от image3 не исправлены. Художественное1:1не принято.';r['status']='REWORK'
 elif r['id'] in ['N11','N14']:r['actual']='v598:8suites/33pixel pairs/7публичных сценариев/107SHA подтверждены;150protected/32backup сохранены. Строгая повторяемость оговорена в отчёте. G04/G07/G08 открыты.'
 else:continue
 r['evidence']='design/c7-release-v598-2026-10-29.md; evidence/c7-v598-completion-status.json'
